import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Administrator troubleshooting","description":"","frontmatter":{"pageId":"admins/troubleshooting","contentRevision":1},"headers":[],"relativePath":"en/admins/troubleshooting.md","filePath":"en/admins/troubleshooting.md"}'),i={name:"en/admins/troubleshooting.md"};function n(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="administrator-troubleshooting" tabindex="-1">Administrator troubleshooting <a class="header-anchor" href="#administrator-troubleshooting" aria-label="Permalink to &quot;Administrator troubleshooting&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Startup failure:</strong> check SDK/runtime, DataDir permissions, occupied port, certificate and the Options validation error. Do not “fix” it by deleting the database.</p><p><strong>Panel works but game fails:</strong> check HTTP/2/gRPC, proxy, TLS and game versions. Loading HTML does not verify the whole transport.</p><p><strong>401/403:</strong> check legacy versus named token, scopes, cookie CSRF and session expiry; do not grant admin to an integration without cause.</p><p><strong>Stalled settlement:</strong> inspect freezes, debt, threats, expiry and escrow ID; examine audit/state before retrying a mutation.</p><p><strong>Restore failure:</strong> verify the server is stopped, the backup is intact and database/saves match; preserve current data before further action.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not dump environment secrets into a shared ticket. Do not terminate unrelated processes. If the cause is unknown, collect exact refusal, version, time and a redacted log excerpt; one /health response does not prove a fix.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./monitoring">Monitoring and event feed</a></li><li><a href="./backup-recovery">Backup and recovery</a></li><li><a href="./../players/troubleshooting">Player troubleshooting</a></li></ul>',12)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
